UPDATE qr_morph_display_blocks SET data_json='{"groups":[{"form_ar":"الفعل — Verb","items":[{"ar":"كَتَبَ","en":"to write; to prescribe (I)","ur":"لکھنا؛ فرض کرنا (I)"},{"ar":"كاتَبَ","en":"to correspond; to contract manumission (III)","ur":"خط و کتابت کرنا؛ مکاتبت کرنا (III)"},{"ar":"اكْتَتَبَ","en":"to have (something) written; to copy (VIII)","ur":"لکھوانا؛ نقل کرنا (VIII)"}]},{"form_ar":"اسم الفاعل — Active participle","items":[{"ar":"كاتِب","en":"writer, scribe","ur":"لکھنے والا، کاتب"}]},{"form_ar":"اسم المفعول — Passive participle","items":[{"ar":"مَكْتوب","en":"written; prescribed, decreed","ur":"لکھا ہوا؛ فرض کیا ہوا"}]},{"form_ar":"المصادر والأسماء — Nouns","items":[{"ar":"كِتاب","en":"book, scripture","ur":"کتاب، صحیفہ"},{"ar":"كِتابة","en":"writing (the act/craft)","ur":"کتابت (فن/عمل)"},{"ar":"كَتيبة","en":"battalion (a gathered troop)","ur":"کتیبہ — جُڑا ہوا لشکری دستہ"},{"ar":"كُتّاب","en":"scribes; a writing-school","ur":"کاتب لوگ؛ مکتب"}]}]}', updated_at=datetime('now') WHERE id='MDB:root:كتب:derivations';
UPDATE qr_morph_display_blocks SET data_json='{"groups":[{"form_ar":"الفعل — Verb","items":[{"ar":"نَزَلَ","en":"to descend, alight, lodge (I)","ur":"اترنا، جا ٹھہرنا (I)"},{"ar":"نَزَّلَ","en":"to send down piecemeal/gradually (II)","ur":"تھوڑا تھوڑا اتارنا (II)"},{"ar":"أَنْزَلَ","en":"to send down, cause to descend (IV)","ur":"اتارنا (IV)"},{"ar":"تَنَزَّلَ","en":"to come down in stages (V)","ur":"درجہ بدرجہ اترنا (V)"},{"ar":"اسْتَنْزَلَ","en":"to seek to bring down (X)","ur":"اتارنے کی طلب کرنا (X)"}]},{"form_ar":"المصادر — Verbal nouns","items":[{"ar":"تَنْزيل","en":"sending-down; the revelation","ur":"تنزیل؛ وحی کا اتار"},{"ar":"إنْزال","en":"a sending-down (all-at-once)","ur":"یکبارگی اتار"},{"ar":"نُزول","en":"descent, alighting","ur":"نزول، اترنا"}]},{"form_ar":"الأسماء — Nouns","items":[{"ar":"مَنْزِل","en":"dwelling; stage of a journey","ur":"ٹھکانا؛ سفر کی منزل"},{"ar":"مَنْزِلة","en":"rank, standing, status","ur":"مرتبہ، مقام"},{"ar":"نُزُل","en":"hospitality fare, provision for a guest","ur":"مہمان کا سامانِ ضیافت"},{"ar":"نَزيل","en":"guest, lodger, resident","ur":"مہمان، مقیم"}]}]}', updated_at=datetime('now') WHERE id='MDB:root:نزل:derivations';
UPDATE qr_morph_display_blocks SET data_json='{"items":[{"ayah_key":"44:2","kind_ar":"الكتاب","en":"the Book","motif":"arrival","text_ar":"وَالْكِتَابِ الْمُبِينِ","note":"Book — clear in itself and clarifying: the study locus.","note_ur":"کتاب — خود روشن اور روشن کرنے والی: زیرِ مطالعہ مقام۔","focus":true,"icon":"star","ur":"کتاب"},{"ayah_key":"26:195","kind_ar":"اللسان","en":"the tongue","motif":"family","text_ar":"بِلِسَانٍ عَرَبِيٍّ مُبِينٍ","note":"Tongue — a clear Arabic speech; clarity as intelligible language.","note_ur":"زبان — کھلی عربی گفتار؛ وضاحت بطور قابلِ فہم زبان۔","icon":"git-fork","ur":"زبان"},{"ayah_key":"36:12","kind_ar":"السِّجِلّ","en":"the record","motif":"shape","text_ar":"أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ","note":"Record — a register that lays every deed out plainly; eschatological ledger.","note_ur":"دفتر — ہر عمل کو کھول کر رکھنے والا رجسٹر؛ اخروی بہی۔","icon":"layout-grid","ur":"دفتر"},{"ayah_key":"2:168","kind_ar":"العداوة","en":"the enemy","motif":"split","text_ar":"إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ","note":"Enemy — Satan as an open, declared foe; clarity as being out in the open.","note_ur":"دشمن — شیطان کھلا، اعلانیہ بدخواہ؛ وضاحت بمعنی سامنے آ جانا۔","icon":"split","ur":"دشمن"},{"ayah_key":"16:35","kind_ar":"التبليغ","en":"the conveyance","motif":"parting","text_ar":"إِلَّا الْبَلَاغُ الْمُبِينُ","note":"Conveyance — the messengers'' task is only the clear delivery itself.","note_ur":"تبلیغ — رسولوں کا کام بس واضح پہنچا دینا۔","icon":"sunrise","ur":"تبلیغ"},{"ayah_key":"5:110","kind_ar":"على ألسنة المنكرين","en":"on deniers’ tongues","motif":"debate","text_ar":"إِنْ هَٰذَا إِلَّا سِحْرٌ مُبِينٌ","note":"Sorcery — مُبِين on the deniers'' tongue: ''plain magic'', clarity turned into accusation.","note_ur":"جادو — منکروں کی زبان پر «کھلا جادو»: وضاحت الزام بن گئی۔","icon":"scale","ur":"منکروں کی زبان پر"},{"ayah_key":"67:26","kind_ar":"الإنذار","en":"the warning","motif":"debate","text_ar":"وَإِنَّمَا أَنَا نَذِيرٌ مُبِينٌ","note":"Warner — the Prophet himself as the one who makes the warning plain.","note_ur":"نذیر — نبی خود تنبیہ کو کھول کر بیان کرنے والے۔","icon":"scale","ur":"تنبیہ"}]}', updated_at=datetime('now') WHERE id='MDB:root:بين:occurrences';
UPDATE qr_morph_display_blocks SET data_json='{"items":[{"ayah_key":"44:2","kind_ar":"الكتاب المبين","en":"the clear Book","motif":"revelation","text_ar":"وَالْكِتَابِ الْمُبِينِ","note":"القرآنُ المُقسَمُ به، الموصوفُ بالإبانة","note_en":"The Qurʾān sworn by, described as self-evidencing (mubīn).","note_ur":"وہ قرآن جس کی قسم کھائی گئی اور جو وضاحت سے موصوف ہے۔","focus":true,"icon":"star","ur":"روشن کتاب"},{"ayah_key":"17:14","kind_ar":"كتابُ الأعمال","en":"the record of deeds","motif":"split","text_ar":"اقْرَأْ كِتَابَكَ","note":"صحيفةُ العمل التي كتبها الحفَظة، يقرؤها المرءُ على نفسه","note_en":"The deed-scroll the recording angels wrote; one reads it against oneself.","note_ur":"اعمال نامہ جو محافظ فرشتوں نے لکھا؛ انسان خود اپنے خلاف پڑھتا ہے۔","icon":"quote","ur":"اعمال نامہ"},{"ayah_key":"27:28","kind_ar":"كتابُ سليمان","en":"a written letter","motif":"arrival","text_ar":"اذْهَب بِّكِتَابِي هَٰذَا","note":"رسالةٌ مكتوبة أرسلها سليمانُ إلى ملكة سبأ","note_en":"A written missive Solomon sent to the Queen of Sheba.","note_ur":"لکھا ہوا خط جو سلیمانؑ نے ملکہ سبا کو بھیجا۔","icon":"feather","ur":"لکھا ہوا خط"},{"ayah_key":"13:39","kind_ar":"أمُّ الكتاب","en":"the archetype/decree","motif":"shape","text_ar":"وَعِندَهُ أُمُّ الْكِتَابِ","note":"أصلُ الكتاب وجملتُه عند الله — الثابتُ الذي عليه المحوُ والإثبات","note_en":"The origin and whole of the Book with God — the fixed source over which erasing and fixing occur.","note_ur":"کتاب کی اصل اور کل اللہ کے پاس — وہ ثابت ماخذ جس پر محو و اثبات چلتا ہے۔","icon":"key-round","ur":"امّ الکتاب"}]}', updated_at=datetime('now') WHERE id='MDB:root:كتب:occurrences';
UPDATE qr_morph_display_blocks SET data_json='{"items":[{"ayah_key":"44:3","kind_ar":"إنزالُ الكتاب","en":"the Book sent down","motif":"revelation","text_ar":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ","note":"إنزالُ القرآنِ جملةً في الليلةِ المباركة — جوابُ القسم بالكتاب المبين","note_en":"The Qurʾān sent down whole on the blessed night — the answer to the oath by the clarifying Book (44:2).","note_ur":"مبارک رات میں قرآن کا یکبارگی نزول — کتابِ مبین کی قسم کا جواب (۴۴:۲)۔","focus":true,"icon":"star","ur":"کتاب کا نزول"},{"ayah_key":"2:185","kind_ar":"شهرُ الإنزال","en":"the month of revelation","motif":"arrival","text_ar":"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ","note":"رمضانُ ظرفُ إنزالِ القرآن، هُدًى للناس","note_en":"Ramadan as the vessel of the Qurʾān’s descent — guidance for humankind.","note_ur":"رمضان قرآن کے نزول کا ظرف — لوگوں کے لیے ہدایت۔","icon":"book-open","ur":"نزول کا مہینہ"},{"ayah_key":"6:99","kind_ar":"إنزالُ الماء","en":"sending down water","motif":"shape","text_ar":"وَهُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً","note":"النُّزولُ الكونيّ — إنزالُ الغيثِ سببِ الحياة","note_en":"The creational descent — rain sent down as the cause of life.","note_ur":"کائناتی نزول — بارش کا اتارا جانا، زندگی کا سبب۔","icon":"sunrise","ur":"پانی کا اتار"},{"ayah_key":"25:32","kind_ar":"التنزيلُ المُنجَّم","en":"the staged sending-down","motif":"split","text_ar":"لَوْلَا نُزِّلَ عَلَيْهِ الْقُرْآنُ جُمْلَةً وَاحِدَةً","note":"اعتراضُهم على التفريق — و«نَزَّلَ» للتنزيلِ المُنجَّم مقابلَ «أَنْزَلَ» الجُمليّ","note_en":"Their objection to piecemeal delivery — nazzala marks the staged descent against the all-at-once anzala.","note_ur":"تفریق پر ان کا اعتراض — «نزّل» درجہ بدرجہ نزول کے لیے، «أنزل» یکبارگی کے مقابل۔","icon":"split","ur":"تدریجی نزول"}]}', updated_at=datetime('now') WHERE id='MDB:root:نزل:occurrences';
