UPDATE qr_morph_display_blocks SET data_json='{"role_ar":"مُقسَمٌ به","role_en":"the sworn-by (genitive)","role_ur":"مُقسَم بہ (مجرور)","position_ar":"مجرورٌ بواو القسم، متعلّقٌ بفعلٍ محذوفٍ تقديرُه أَقْسِمُ","sign_ar":"الكسرة","sources":["الإعراب الميسّر: الواو واو القسم، «الكتاب» مجرور بها، «المبين» نعت للكتاب","الجدول في إعراب القرآن: «الكتاب» متعلّق بفعلٍ محذوف تقديره أقسم؛ «إنّا أنزلناه» جواب القسم لا محلّ لها","إعراب الدرويش: تقدّم نظيرُه في الزخرف؛ «إنّا أنزلناه» جواب القسم"]}', updated_at=datetime('now') WHERE id='MDB:ctx:كتب:44:2:irab';
UPDATE qr_morph_display_blocks SET data_json='{"role_ar":"مفعولٌ به","role_en":"direct object (accusative)","role_ur":"مفعول بہ (منصوب)","position_ar":"مقولُ قولٍ محذوف (يُقالُ له)؛ الكافُ مضافٌ إليه","sign_ar":"الفتحة","sources":["الإعراب الميسّر: «اقرأ كتابك» في موضع نصبٍ مقولُ قولٍ محذوف؛ «كتابك» مفعولٌ به","إعراب الدعّاس: «كتاب» مفعولٌ به والكافُ مضافٌ إليه، والجملةُ مقولُ القول لفعلٍ محذوف تقديره يُقال له","التبيان (العُكبري): «اقرأ» أي يُقال له"]}', updated_at=datetime('now') WHERE id='MDB:ctx:كتب:17:14:irab';
UPDATE qr_morph_display_blocks SET data_json='{"role_ar":"اسمٌ مجرورٌ بالباء","role_en":"genitive after the preposition bāʾ","role_ur":"حرفِ جر «با» کے بعد مجرور","position_ar":"جارٌّ ومجرور متعلّقان بـ«اذهب»؛ الياءُ مضافٌ إليه؛ «هذا» نعتٌ أو بدلٌ/عطفُ بيان","sign_ar":"الكسرة","sources":["الإعراب الميسّر: «بكتابي» جارٌّ ومجرور متعلّقان بـ«اذهب»، و«هذا» نعتٌ لكتابي أو بدلٌ منه","الجدول في إعراب القرآن: «بكتابي» متعلّق بـ«اذهب»؛ «هذا» عطفُ بيانٍ على كتابي أو بدلٌ منه في محلّ جرّ","إعراب الدرويش: ثم كتب سليمانُ كتاباً هذه صورتُه — أي كتابٌ مكتوبٌ مُرسَل"]}', updated_at=datetime('now') WHERE id='MDB:ctx:كتب:27:28:irab';
UPDATE qr_morph_display_blocks SET data_json='{"role_ar":"مبتدأٌ مؤخَّر (أُمّ) في إضافةِ «أُمّ الكتاب»","role_en":"delayed subject in the iḍāfa “Mother of the Book”","role_ur":"مبتدائے مؤخر — اضافت «امّ الکتاب» میں","position_ar":"الخبرُ مقدَّمٌ شبهُ جملة (عنده)؛ «الكتابِ» مضافٌ إليه مجرور","sign_ar":"الضمة (أُمّ) / الكسرة (الكتاب)","sources":["الإعراب الميسّر: «عنده» ظرفٌ متعلّقٌ بمحذوفٍ خبرٍ مقدَّم، و«أمّ» مبتدأٌ مؤخَّر، و«الكتاب» مضافٌ إليه","إعراب الدعّاس: «أمّ» مبتدأٌ مؤخَّر، «عند» ظرفٌ متعلّقٌ بالخبرِ المقدَّم، «الكتاب» مضافٌ إليه، والجملةُ مستأنفة","الجدول: لا محلَّ لها معطوفةٌ على الاستئنافيّة؛ وفي «لكلِّ أجلٍ كتاب» فنُّ الاستخدام (الأجلُ المكتوب والسِّجِلّ)"]}', updated_at=datetime('now') WHERE id='MDB:ctx:كتب:13:39:irab';
UPDATE qr_morph_display_blocks SET data_json='{"role_ar":"فعلٌ ماضٍ (الهاءُ مفعولٌ به يعودُ على القرآن)","role_en":"perfect verb — the ـه is its object (the Qurʾān)","role_ur":"فعلِ ماضی — «ہ» اس کا مفعول، مرجع قرآن","position_ar":"نا الفاعلين فاعلٌ؛ وجملةُ «أنزلناه» في محلّ رفع خبرُ إنّ، وهي جوابُ القسم","sign_ar":"مبنيٌّ على السكون","sources":["الإعراب الميسّر: «أنزلناه» فعلٌ ماضٍ، و«نا» فاعل، والهاءُ مفعولٌ به، والجملةُ خبرُ إنّ؛ و«في ليلة» جارٌّ ومجرور متعلّقان بأنزلناه، و«مباركة» نعتٌ لليلة، وجملةُ «إنّا أنزلناه» جوابُ القسم","التبيان (العُكبري): «إنّا أنزلناه» هو جوابُ القسم، و«إنّا كنّا» مستأنَف"]}', updated_at=datetime('now') WHERE id='MDB:ctx:نزل:44:3:irab';
UPDATE qr_morph_display_blocks SET data_json='{"formula_ar":"كِتَاب + مُبِين","formula_en":"the كتاب-مبين formula binds revelation to intelligibility","formula_ur":"ترکیب «کتاب + مبین» وحی کو فہم پذیری سے باندھ دیتی ہے","refs":["43:2","12:1","26:2","27:1","28:2"]}', updated_at=datetime('now') WHERE id='MDB:ctx:بين:44:2:balagha';
UPDATE qr_morph_display_blocks SET data_json='{"formula_ar":"قَسَمٌ (كِتاب) + نعت (مُبِين)","formula_en":"the كتاب-مبين oath binds revelation to its own clarity","formula_ur":"قسم (کتاب) + نعت (مبین) — وحی اپنی ہی وضاحت سے بندھی ہوئی","refs":["43:2","44:2","12:1","26:2","27:1","28:2"]}', updated_at=datetime('now') WHERE id='MDB:ctx:كتب:44:2:balagha';
UPDATE qr_morph_display_blocks SET data_json='{"formula_ar":"إنزالٌ جُمليّ (أَنْزَلَ) + ضميرُ التعظيم (إنّا) + جوابُ قسم","formula_en":"the all-at-once anzala + the majestic “We” + the oath-answer — dignifying the Book’s descent","formula_ur":"یکبارگی اتار (أنزل) + ضمیرِ تعظیم (إنا) + جوابِ قسم — کتاب کے نزول کی شان","refs":["97:1","2:185","25:32","17:93","3:3","44:2"]}', updated_at=datetime('now') WHERE id='MDB:ctx:نزل:44:3:balagha';
UPDATE qr_morph_display_blocks SET data_json='{"witnesses":[{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"البَيْن · الفِراق","phrase_ar":"غُرابُ البَيْن","gloss_en":"“the crow of parting” — a fixed idiom: the raven whose cawing over an abandoned camp was read as the omen that the tribe, and the beloved, would depart.","gloss_ur":"«غرابِ بین» — جدائی کا کوا: مستقل محاورہ؛ اجڑے پڑاؤ پر اس کی کائیں کائیں اس کا شگون سمجھی جاتی کہ قبیلہ اور محبوب رخصت ہونے والے ہیں۔","image_ar":"غرابٌ أسود ينعق فوق ديارٍ خاوية","image_en":"a black crow over an emptied campsite — separation announced","image_ur":"خالی دیاروں پر کائیں کائیں کرتا کالا کوا — جدائی کا اعلان","lex_source":"ابن فارس · مقاييس اللغة","lex_ar":"البَيْنُ هو الانفصال","lex_en":"al-bayn = the separation itself (d. 395 AH)","lex_ur":"البَین یعنی خود جدائی (م ۳۹۵ھ)","motif":"parting","icon":"sunrise"},{"era_ar":"مَثَلٌ سائر","era_en":"Proverb","kind_ar":"بانَ · ظَهَر","phrase_ar":"قد بانَ الصُّبْحُ لِذي عَيْنَيْن","gloss_en":"“the dawn has shown itself to anyone with eyes” — the proverb for a truth now beyond any denial; what parts from the dark becomes plain to all.","gloss_ur":"«صبح ہر دو آنکھوں والے پر ظاہر ہو چکی» — اس سچائی کی مثل جو اب کسی انکار سے بالاتر ہے؛ جو اندھیرے سے الگ ہوا وہ سب پر عیاں ہو گیا۔","image_ar":"فجرٌ ينفصل عن الليل فيراه كلُّ ذي بصر","image_en":"dawn splitting off from night, plain to every eye","image_ur":"رات سے الگ ہوتی فجر، ہر آنکھ پر عیاں","lex_source":"الرّاغب · المفردات","lex_ar":"بانَ الصُّبحُ: ظهرَ ما كان مُستترًا","lex_en":"al-Rāghib''s own shāhid: bāna l-ṣubḥ — the dawn showed (d. 502 AH)","lex_ur":"راغب کا اپنا شاہد: بانَ الصبح — صبح ظاہر ہوئی (م ۵۰۲ھ)","motif":"arrival","icon":"star"},{"era_ar":"النَّسيب","era_en":"Ode-opening","kind_ar":"بانَ الخَليط · المسافة","phrase_ar":"بانَ الخَليطُ ولم يَأْذَنوا برَحيلِهِمِ","gloss_en":"“the companions parted and gave no warning of leaving” — the ode''s classic opening formula: the mingled camp pulls away across the sand and the interval (بَيْن) between lovers opens.","gloss_ur":"«ساتھی بچھڑ گئے اور رخصت کی خبر تک نہ دی» — قصیدے کا کلاسیکی آغاز: ملا جلا پڑاؤ ریت پار کھنچ جاتا ہے اور محبوبوں کے بیچ «بَین» کا فاصلہ کھل جاتا ہے۔","image_ar":"ظَعائنُ ترحل والغبارُ يفصل بين الأحبّة","image_en":"a caravan pulling away, dust widening the gap between lovers","image_ur":"روانہ ہوتے ہودج، اور غبار محبوبوں کے درمیان فاصلہ بڑھاتا ہوا","lex_source":"الرّاغب · المفردات","lex_ar":"البَيْن: الفَصلُ بين الشيئين","lex_en":"al-bayn = the interval between two things (d. 502 AH)","lex_ur":"البَین: دو چیزوں کے درمیان کا فصل (م ۵۰۲ھ)","motif":"split","icon":"split"},{"era_ar":"الخَطابة","era_en":"Oratory","kind_ar":"البَيان · الفصاحة","phrase_ar":"أوتِيَ بَيانًا","gloss_en":"“he was granted bayān” — clear, distinct speech that sets each meaning apart from the next; the most prized virtue of the pre-Islamic orator.","gloss_ur":"«اسے بیان عطا ہوا» — صاف، جدا جدا گفتار جو ہر معنی کو دوسرے سے الگ کر دے؛ جاہلی خطیب کی سب سے قیمتی خوبی۔","image_ar":"لسانٌ يفصل المعاني فتقفُ كلٌّ على حِدَة","image_en":"a tongue that separates meanings so each stands on its own","image_ur":"ایسی زبان جو معانی کو الگ کرے کہ ہر ایک اپنی جگہ کھڑا ہو","lex_source":"الرّاغب · سِنائي","lex_ar":"بَيان · مُبَيِّن · مُستَبِين","lex_en":"the root''s clarity-cluster — Rāghib & Sinai","lex_ur":"مادّے کا خوشۂ وضاحت — راغب و سینائی","motif":"family","icon":"git-fork"}]}', updated_at=datetime('now') WHERE id='MDB:root:بين:attestations';
UPDATE qr_morph_display_blocks SET data_json='{"witnesses":[{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"حسّي","phrase_ar":"كَتَبَ السِّقاءَ","gloss_en":"stitched the waterskin shut","gloss_ur":"مشکیزہ سی کر بند کیا","image_ar":"ضمُّ أديمٍ إلى أديم","image_en":"binding hide to hide","image_ur":"چمڑے کو چمڑے سے جوڑنا","lex_source":"Kitāb al-ʿAyn","lex_ar":"الكَتْبُ: الخَرْزُ بسَيرَين","lex_en":"to sew with two thongs","lex_ur":"الکَتْب: دو تسموں سے سینا","motif":"shape","icon":"link"},{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"حربي","phrase_ar":"كَتيبةٌ خَضراء","gloss_en":"a dense (iron-grey) battalion","gloss_ur":"گٹھا ہوا، آہنی رنگ لشکری دستہ","image_ar":"الجماعةُ المجتمعة من الجيش","image_en":"a massed troop","image_ur":"فوج کا جُڑا ہوا جتھا","lex_source":"Lisān al-ʿArab","lex_ar":"الكَتيبة: الجماعةُ المستكتِبة","lex_en":"the gathered company","lex_ur":"کتیبہ: سمٹی ہوئی جماعت","motif":"family","icon":"landmark"},{"era_ar":"صدر الإسلام","era_en":"Early Islamic","kind_ar":"وثائقي","phrase_ar":"كِتابُ النبيِّ ﷺ","gloss_en":"the Prophet’s written pact/letter","gloss_ur":"نبی ﷺ کا لکھا ہوا عہد نامہ/خط","image_ar":"الصحيفةُ والعهد المكتوب","image_en":"a written pact","image_ur":"صحیفہ اور لکھا ہوا عہد","lex_source":"Mufradāt","lex_ar":"الكِتاب: ما يُضَمُّ من الحروف","lex_en":"letters bound together","lex_ur":"الکتاب: جڑے ہوئے حروف","motif":"arrival","icon":"quote"},{"era_ar":"قرآني","era_en":"Qurʾānic","kind_ar":"حُكمي","phrase_ar":"كُتِبَ عليكم","gloss_en":"it is prescribed upon you","gloss_ur":"تم پر فرض کیا گیا","image_ar":"الفَرْضُ المُثبَت","image_en":"a fixed ordinance","image_ur":"طے شدہ فریضہ","lex_source":"Lisān al-ʿArab","lex_ar":"كَتَبَ اللهُ الشيءَ: قضاه","lex_en":"God decreed it","lex_ur":"کتب اللہ الشیء: اس نے فیصلہ فرمایا","motif":"split","icon":"key-round"}]}', updated_at=datetime('now') WHERE id='MDB:root:كتب:attestations';
UPDATE qr_morph_display_blocks SET data_json='{"witnesses":[{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"حسّي","phrase_ar":"نَزَلَ الراكبُ بالوادي","gloss_en":"the rider alighted in the valley","gloss_ur":"سوار وادی میں اترا","image_ar":"الهُبوطُ والحُلولُ بالمكان","image_en":"descending and lodging at a place","image_ur":"کسی جگہ اترنا اور ٹھہرنا","lex_source":"Kitāb al-ʿAyn","lex_ar":"نَزَلَ من عُلوٍّ إلى سُفل","lex_en":"descent from a height to a lower place","lex_ur":"بلندی سے پستی کی طرف اترنا","motif":"split","icon":"trending-up"},{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"ضِيافي","phrase_ar":"أحسنَ نُزُلَه","gloss_en":"he gave him fine hospitality","gloss_ur":"اس نے اس کی خوب مہمانی کی","image_ar":"ما يُهيَّأ للنازلِ من قِرى","image_en":"the fare prepared for one who alights","image_ur":"اترنے والے کے لیے تیار سامانِ ضیافت","lex_source":"Lisān al-ʿArab","lex_ar":"النُّزُل: ما يُهيَّأ للضيف","lex_en":"provision readied for a guest","lex_ur":"النُّزُل: مہمان کے لیے تیار کردہ","motif":"arrival","icon":"landmark"},{"era_ar":"الجاهلية","era_en":"Pre-Islamic","kind_ar":"اصطلاحيّ","phrase_ar":"نَزَلَ بهم المكروهُ","gloss_en":"the calamity descended upon them","gloss_ur":"ان پر آفت اتر پڑی","image_ar":"النازلةُ: الشِّدّةُ تَنزِل بالقوم","image_en":"a nāzila — a hardship that befalls a people","image_ur":"نازلہ: قوم پر اترنے والی سختی","lex_source":"Mir, Verbal Idioms","lex_ar":"نَزَلَ بِه: حَلَّ به المكروهُ (نزل بساحتهم)","lex_en":"the idiom “nazala bi-” = to befall (cf. 37:177)","lex_ur":"محاورہ «نزل بہ» = آ پڑنا (دیکھیے ۳۷:۱۷۷)","motif":"split","icon":"quote"},{"era_ar":"قرآني","era_en":"Qurʾānic","kind_ar":"كوني","phrase_ar":"أَنْزَلَ من السماءِ ماءً","gloss_en":"He sent down water from the sky","gloss_ur":"اس نے آسمان سے پانی اتارا","image_ar":"إنزالُ الغيثِ والرزق","image_en":"the sending-down of rain and provision","image_ur":"بارش اور رزق کا اتارا جانا","lex_source":"Mufradāt","lex_ar":"أَنْزَلَ: عامٌّ في المُفرَّق والمجموع","lex_en":"anzala — general, all-at-once or piecemeal","lex_ur":"أنزل — عام: یکبارگی ہو یا تھوڑا تھوڑا","motif":"shape","icon":"sunrise"},{"era_ar":"قرآني","era_en":"Qurʾānic","kind_ar":"وحيانيّ","phrase_ar":"إِنَّا أَنْزَلْنَاهُ","gloss_en":"We sent it (the Qurʾān) down","gloss_ur":"بیشک ہم ہی نے اسے (قرآن کو) اتارا","image_ar":"تنزيلُ الوحيِ من عند الله","image_en":"the sending-down of revelation from God","image_ur":"اللہ کی طرف سے وحی کا نزول","lex_source":"al-Burhān","lex_ar":"أُنزِل جملةً ثم نُزِّل نُجوماً","lex_en":"sent down whole, then in stages","lex_ur":"پہلے یکبارگی اترا، پھر نجوماً (تھوڑا تھوڑا)","motif":"revelation","icon":"book-open"}]}', updated_at=datetime('now') WHERE id='MDB:root:نزل:attestations';
UPDATE qr_morph_display_blocks SET data_json='{"medallion_ar":"مُبِين","medallion_root":"ب ي ن","threads":["root DNA","wazn IV","derivations","iʿrāb","lexicons","balāgha","translators","usage map"],"movements":[{"no":"I","motif":"parting","en":"The Picture","ar":"الصورة","accent":"#c9a84c","icon":"sunrise","text":"يبدأ الجذرُ صورةً للفراق — طريقٌ يشقُّ الصحراء، وفجرٌ ينفصل عن الليل. فأقدمُ معاني «ب ي ن» انفصالٌ يُفضي إلى الرؤية: ما بانَ وانفصل فقد ظهر.","text_ur":"آغاز جدائی کی ایک تصویر سے ہوتا ہے — صحرا کو چیرتا راستہ، رات سے الگ ہوتی فجر۔ مادّے کا قدیم ترین معنی وہ جدائی ہے جو دِکھنے پر منتج ہو: جو الگ کھڑا ہوا وہ نظر آنے لگا۔","text_en":"It begins as a picture of parting — a road cutting the desert, dawn breaking off from night. The root’s oldest sense is a separation that leads to sight: what stands apart becomes visible."},{"no":"II","motif":"family","en":"The Family","ar":"الأسرة","accent":"#7fb58f","icon":"git-fork","text":"من هذا الجذر الواحد «ب ي ن» تنبتُ أسرةٌ كاملة — كلُّ بناءٍ هو الفكرةُ نفسها وقد انكسرتْ في وزن.","text_ur":"اسی ایک جڑ «ب ی ن» سے عربی ایک پورا کنبہ اگاتی ہے — ہر سانچہ وہی خیال، کسی وزن میں ڈھلا ہوا۔","chips":[{"ar":"بَيْن","en":"the gap between","ur":"درمیانی فاصلہ"},{"ar":"بانَ","en":"to show","ur":"ظاہر ہونا"},{"ar":"بيَّنَ","en":"to make clear","ur":"واضح کرنا"},{"ar":"أبانَ","en":"to clarify","ur":"روشن کر دینا"},{"ar":"بيان","en":"clear speech","ur":"کھلی گفتار"},{"ar":"بيِّنة","en":"a standing proof","ur":"قائم دلیل"}],"text_en":"From that one root, ب ي ن, Arabic grows a whole family — every build the same idea refracted through a pattern."},{"no":"III","motif":"arrival","en":"The Arrival","ar":"الورود","accent":"#e8c96a","icon":"star","text":"وفي ٤٤:٢ يَرِدُ الجذرُ بصيغة «مُبِين» — اسمِ فاعلِ الإفعال على وزن مُفْعِل. ولأنّ البابَ لازمٌ ومتعدٍّ معًا، يدّعي اللفظُ أمرين في نَفَسٍ واحد: الكتابُ بيِّنٌ في نفسه، ومُبِينٌ لكلِّ شيءٍ سواه.","text_ur":"۴۴:۲ پر مادّہ «مُبین» بن کر وارد ہوتا ہے — بابِ افعال کا اسم فاعل، وزن مُفعِل پر۔ چونکہ یہ باب بیک وقت لازم اور متعدی ہے، لفظ ایک سانس میں دو دعوے کرتا ہے: کتاب خود روشن ہے، اور باقی سب کو روشن کرتی ہے۔","text_en":"At 44:2 the root arrives as مُبِين — the active participle of Form IV on the pattern مُفْعِل. Because that form is at once intransitive and transitive, the word claims two things in one breath: the Book is clear in itself, and it makes all else clear."},{"no":"IV","motif":"debate","en":"The Argument","ar":"الحجّة","accent":"#93b8d6","icon":"scale","text":"يجعله النحويّون نعتًا للكتاب مجرورًا في القسم. لكنّ البلاغيين يُرون أنّ القسمَ نفسَه هو الحجّة: يُقسِم اللهُ بالكتاب، على الكتاب — والوصفُ الواحد «مبين» يحمل البرهانَ كلَّه.","text_ur":"نحوی اسے قسم میں «الکتاب» کی محض صفتِ مجرور ٹھہراتے ہیں۔ مگر اہلِ بلاغت دکھاتے ہیں کہ قسم بذاتِ خود دلیل ہے: اللہ کتاب کی قسم کھاتا ہے، کتاب ہی کے بارے میں — اور اکیلا وصف «مبین» پورا استدلال اٹھائے ہوئے ہے۔","text_en":"The grammarians place it as a mere adjective of الكتاب, genitive in the oath. Yet the rhetoricians show the oath itself IS the argument: God swears by the Book, about the Book — and the single epithet مُبِين carries the whole proof."},{"no":"V","motif":"split","en":"The Split","ar":"الترجمة","accent":"#b3a6f6","icon":"split","text":"من هنا افترق المترجمون: «الكتابُ الواضح» يُبقي نصفَ المعنى؛ و«الكتابُ الذي يُبين» يستردُّ التعديةَ — وهي الدعوى التي تُطلقها صيغةُ «كتاب مبين» وتتردّد في ٤٣:٢ و١٢:١ و٢٦:٢ و٢٧:١ و٢٨:٢.","text_ur":"اسی لیے مترجم بٹ جاتے ہیں۔ «واضح کتاب» صرف آدھا رکھتا ہے؛ «چیزوں کو واضح کرنے والی کتاب» متعدی قوت لوٹا دیتا ہے — وہی دعویٰ جو ترکیب «کتاب مبین» دراصل کر رہی ہے، اور جو ۴۳:۲، ۱۲:۱، ۲۶:۲، ۲۷:۱ اور ۲۸:۲ میں گونجتا ہے۔","text_en":"This is why translators split. “The clear Book” keeps only half; “the Book that makes things clear” recovers the causative — the claim the formula كتاب مبين is really making, echoing across 43:2, 12:1, 26:2, 27:1 and 28:2."},{"no":"VI","motif":"shape","en":"The Shape","ar":"الخريطة","accent":"#c9a84c","icon":"layout-grid","text":"واقرأ خريطةَ الاستعمال تَرَ الشكلَ نفسَه: يتجمّع «مُبِين» في الحقلَين الروحيّ والظهوريّ ويقلُّ في التشريعيّ. فهو أقلُّ ما يكون لفظَ أحكامٍ، وأكثرُ ما يكون لفظَ وحيٍ يخرج من الخفاء ليقفَ أخيرًا في العَراء.","text_ur":"نقشۂ استعمال پڑھیے تو وہی صورت ابھرتی ہے: «مبین» روحانی اور ظہوری خانوں میں سمٹتا ہے اور قانونی خانے کی طرف چھدرا ہوتا جاتا ہے۔ یہ قواعد سے زیادہ اس وحی کا لفظ ہے جو پردے سے نکل کر، آخرکار، کھلے میں آ کھڑی ہوتی ہے۔","text_en":"Read the usage map and the same shape appears: مُبِين gathers in the spiritual and manifest bands, thinning toward the legal. It is less a word about rules than about revelation stepping out of concealment — standing, at last, in the open."}]}', updated_at=datetime('now') WHERE id='MDB:root:بين:master_story';
UPDATE qr_morph_display_blocks SET data_json='{"medallion_ar":"كِتاب","medallion_root":"ك ت ب","threads":["المعجم","الاشتقاق","التفسير"],"movements":[{"no":"I","motif":"binding","en":"The Binding","ar":"الضمّ","accent":"#c9a84c","icon":"link","text":"كان الكَتْبُ أوّلَ أمرِه ==ضمًّا محسوساً==: خَرْزُ الأديمِ يُلحِمُ طرَفاً بطرَف، وجمعُ الكَتيبةِ يشُدُّ الصفَّ إلى الصفّ. فكلُّ ما جُمِعَ وضُمَّ فقد كُتِبَ — وهو أصلُ ابنِ فارسٍ الواحد: الجمعُ والضمّ.","text_en":"At first كَتْب was a ==binding you could touch==: stitching hide so edge fuses to edge, mustering a battalion so rank locks to rank. Whatever was gathered and joined was “written” — Ibn Fāris’s one root sense: gathering and binding.","text_ur":"کَتْب پہلے پہل ایسا ==چھو سکنے والا جوڑ== تھا: چمڑے کی سلائی کہ کنارہ کنارے سے جُڑ جائے، دستے کی صف بندی کہ قطار قطار سے کس جائے۔ جو کچھ جمع اور ضم ہوا وہ «لکھا گیا» — یہی ابن فارس کا ایک اصل: جمع اور ضم۔","chips":[{"ar":"كَتيبة","en":"battalion","ur":"لشکری دستہ"}]},{"no":"II","motif":"writing","en":"The Writing","ar":"الخطّ","accent":"#7fb58f","icon":"feather","text":"ثم انتقلَ الضمُّ من الأشياءِ إلى ==الحروف==: ضُمَّ حرفٌ إلى حرفٍ بالخطِّ فانعقدَ اللفظُ والمعنى، ونشأتْ أسرةُ الكتابة — الكاتبُ يخُطّ، والمكتوبُ يَثبُت، والكِتابةُ صناعةً. فصار الجمعُ الحسّيُّ جمعاً يحفظُ الكلامَ من الضياع.","text_en":"Then the binding moved from things to ==letters==: sign joined to sign by the pen until word and meaning set, and the family of writing was born — the scribe who inscribes, the written that endures, writing as a craft. The tangible gathering became one that saves speech from loss.","text_ur":"پھر جوڑ چیزوں سے ==حروف== کی طرف بڑھا: قلم سے حرف حرف سے جُڑا تو لفظ اور معنی بندھ گئے، اور کتابت کا کنبہ جنم لینے لگا — کاتب لکھتا ہے، مکتوب باقی رہتا ہے، کتابت ایک فن۔ حسی جمع اب وہ جمع بن گیا جو کلام کو ضائع ہونے سے بچاتا ہے۔","chips":[{"ar":"كاتِب","en":"scribe","ur":"کاتب"}]},{"no":"III","motif":"decree","en":"The Decree","ar":"الفَرْض","accent":"#8878e2","icon":"key-round","text":"وما أُثبِتَ بالخطِّ لا يُمحى، فاستُعيرَ الكَتْبُ ==للحُكمِ الماضي==: «كُتِبَ عليكم الصيام» أي فُرِضَ وأُلزِم، وكَتَبَ اللهُ الشيءَ: قضاه وقدَّره. هكذا رتَّبَ الراغبُ المعنى من ضمِّ الحروفِ إلى الفَرْض، وأبرزَ ابنُ منظورٍ دلالةَ القَدَرِ والقضاء.","text_en":"What the pen fixes is not erased, so كَتْب was borrowed for the ==binding decree==: “kutiba ʿalaykum” — it is prescribed, made binding; “God wrote the thing” — He decreed it. Al-Rāghib ordered the sense from joining letters to prescribing, and Ibn Manẓūr foregrounded fate and decree.","text_ur":"جو قلم سے ثبت ہوا وہ مٹتا نہیں، سو کَتْب ==اٹل حکم== کے لیے مستعار ہوا: «کُتِبَ علیکم الصیام» یعنی فرض اور لازم کر دیا گیا؛ «کتب اللہ الشیء» — اس نے فیصلہ فرمایا اور مقدر کیا۔ راغب نے معنی کو حروف کے جوڑ سے فرض تک مرتب کیا، اور ابن منظور نے قضا و قدر کی دلالت نمایاں کی۔","chips":[{"ar":"كُتِبَ عليكم","en":"prescribed","ur":"فرض کیا گیا"}]},{"no":"IV","motif":"scripture","en":"The Book Made Manifest","ar":"الكتاب المبين","accent":"#93b8d6","icon":"book-open","text":"وبلغَ الجذرُ ذروتَه في القرآن: ==كِتابٌ منزَّلٌ== يجمعُ الحرفَ والحُكمَ والوعدَ في وحيٍ واحد، أُقسِمَ به على نزولِه في ليلةٍ مباركة، ووُصِفَ بالمُبينِ لأنه بيِّنٌ في نفسِه مُبيِّنٌ لغيره. فالكتابُ المبينُ عند الزمخشريِّ هو القرآن — غايةُ ما ضُمَّ وأُثبِتَ ثم أبان.","text_en":"In the Qurʾān the root reaches its summit: a ==Book sent down== that binds letter, decree and promise into one revelation, sworn by upon its descent on a blessed night, and called mubīn — clear in itself, clarifying for others. For al-Zamakhsharī the clarifying Book is the Qurʾān: the utmost of what was bound and fixed, then made plain.","text_ur":"اور قرآن میں مادّہ اپنی معراج کو پہنچا: ==نازل شدہ کتاب== جو حرف، حکم اور وعدے کو ایک وحی میں سمو دیتی ہے؛ اسی کی قسم کھائی گئی کہ مبارک رات میں اتری، اور «مبین» کہلائی کہ خود روشن ہے اور دوسروں کے لیے روشن کرنے والی۔ زمخشری کے ہاں الکتاب المبین قرآن ہی ہے — جو کچھ جوڑا اور ثبت ہوا، پھر روشن کیا گیا، اس کی انتہا۔","chips":[{"ar":"المبين","en":"clear","ur":"روشن"}]}]}', updated_at=datetime('now') WHERE id='MDB:root:كتب:master_story';
UPDATE qr_morph_display_blocks SET data_json='{"medallion_ar":"أَنْزَلَ","medallion_root":"ن ز ل","threads":["المعجم","الاشتقاق","التفسير"],"movements":[{"no":"I","motif":"descent","en":"The Descent","ar":"الهُبوط","accent":"#c9a84c","icon":"trending-up","text":"كان النُّزولُ أوّلاً ==هُبوطاً محسوساً==: يهبطُ الراكبُ عن دابّتِه، ويهبطُ الغيثُ من السحاب. وضمَّ ابنُ فارسٍ إلى الهبوطِ معنى الوقوع، فالنازلةُ شِدّةٌ تَنزِل — وأصلُ المادّةِ عنده: هُبوطُ شيءٍ ووقوعُه.","text_en":"At first نزول was a ==descent you could see==: the rider comes down from his mount, the rain comes down from the cloud. Ibn Fāris joins to “descent” the sense of befalling — a nāzila is a hardship that “comes down” — his one root sense: the coming-down of a thing and its landing.","text_ur":"نزول پہلے وہ ==آنکھ سے دیکھا جانے والا اترنا== تھا: سوار سواری سے اترتا ہے، بارش بادل سے۔ ابن فارس نے «اترنے» کے ساتھ «آ پڑنے» کا معنی جوڑا — نازلہ وہ سختی جو اتر پڑے — ان کا ایک اصل: کسی شے کا اترنا اور واقع ہونا۔","chips":[{"ar":"نُزول","en":"descent","ur":"نزول"}]},{"no":"II","motif":"alighting","en":"The Alighting","ar":"الحُلول","accent":"#7fb58f","icon":"landmark","text":"ثم صار الهبوطُ ==حُلولاً==: نَزَلَ بالقومِ فحلَّ بينهم ضيفاً، فنشأ المَنزِلُ موضعاً، والنُّزُلُ قِرًى للضيف، والمَنزِلةُ رُتبةً ومكانة. وعلى الحُلولِ والإقامةِ بنى ابنُ منظورٍ المادّةَ كلَّها.","text_en":"Then descent became ==alighting==: to nazala among a people was to lodge with them as a guest — so manzil became a place, nuzul the fare for a guest, and manzila a rank and standing. Ibn Manẓūr builds the whole root on ḥulūl, taking up residence.","text_ur":"پھر اترنا ==ٹھہرنا== بن گیا: کسی قوم میں نزول کیا تو مہمان بن کر ان میں ٹھہرا — سو منزل جگہ ٹھہری، نُزُل مہمان کا کھانا، اور منزلت رتبہ و مقام۔ ابن منظور پورا مادّہ حلول یعنی اتر کر بسنے پر تعمیر کرتے ہیں۔","chips":[{"ar":"مَنزِل","en":"dwelling","ur":"ٹھکانا"}]},{"no":"III","motif":"sending","en":"The Sending-Down","ar":"الإنزال","accent":"#8878e2","icon":"sunrise","text":"وعدَّت ==همزةُ الإنزال== الفعلَ، فصار اللهُ هو المُنزِل: أنزلَ من السماءِ ماءً ورزقاً ولباساً وحديداً وسكينةً. فالجذرُ يخدمُ الوحيَ والطبيعةَ معاً — نعمةٌ تهبطُ من عُلوٍّ على الخلق.","text_en":"The ==causative hamza== of inzāl made it transitive, so God is the Sender-down: He sent down from the sky water, provision, raiment, iron, and serenity. The root serves both revelation and nature — a grace descending from on high upon creation.","text_ur":"==ہمزۂ تعدیہ== نے فعل کو متعدی کیا تو اللہ ہی اتارنے والا ٹھہرا: اس نے آسمان سے پانی، رزق، لباس، لوہا اور سکینت اتاری۔ مادّہ وحی اور فطرت دونوں کی خدمت کرتا ہے — بلندی سے مخلوق پر اترتی نعمت۔","chips":[{"ar":"أنزل ماءً","en":"sent down water","ur":"پانی اتارا"}]},{"no":"IV","motif":"revelation","en":"The Revelation","ar":"التنزيل","accent":"#93b8d6","icon":"book-open","text":"وبلغَ الجذرُ ذروتَه في ==تنزيلِ الكتاب==: «إنّا أنزلناه في ليلةٍ مباركة» — إنزالٌ من عُلوٍّ لا صُعودَ فيه، الفاعلُ اللهُ وحدَه. واختيرَ «أنزل» للجملةِ دون «نزّل» للتفريق؛ فالوحيُ عند سيناء حركةٌ نازلةٌ من السماء لا يملكُها إلا المُنزِل.","text_en":"And the root reached its summit in the ==sending-down of the Book==: «We sent it down on a blessed night» — a descent from on high with no ascent in it, God its sole agent. anzala (the whole) is chosen over nazzala (the piecemeal); for Sinai, revelation is a downward movement from heaven that only the Sender-down commands.","text_ur":"اور مادّہ ==کتاب کی تنزیل== میں اپنی معراج کو پہنچا: «إنا أنزلناہ فی لیلۃ مبارکۃ» — ایسا اترنا جس میں کوئی چڑھنا نہیں، فاعل صرف اللہ۔ یکبارگی کے لیے «أنزل» چنا گیا، تھوڑا تھوڑا کے «نزّل» کے مقابل؛ سینائی کے نزدیک وحی آسمان سے اترتی وہ حرکت ہے جس پر اتارنے والے کے سوا کسی کا اختیار نہیں۔","chips":[{"ar":"أنزلناه","en":"We sent it down","ur":"ہم نے اسے اتارا"}]}]}', updated_at=datetime('now') WHERE id='MDB:root:نزل:master_story';
UPDATE qr_morph_display_blocks SET data_json='{"renderings":[{"translator":"Abdel Haleem","text":"the Scripture that makes things clear","reading":"causative"},{"translator":"Pickthall","text":"the Scripture that maketh plain","reading":"causative"},{"translator":"Yusuf Ali","text":"the Book that makes things clear","reading":"causative"},{"translator":"Sahih International","text":"the clear Book","reading":"partial"},{"translator":"Jālandharī (اردو)","text":"اس کتابِ روشن کی قسم","reading":"partial"},{"translator":"Kanz al-Īmān (اردو)","text":"قسم اس روشن کتاب کی","reading":"partial"},{"translator":"Tafhīm al-Qurʾān (اردو)","text":"قسم ہے اس کتابِ مبین کی","reading":"transliterates"},{"translator":"K-MAPS gloss","text":"the Book — clear in itself and clarifying","reading":"both"}]}', updated_at=datetime('now') WHERE id='MDB:ctx:بين:44:2:translators';
